command -v go >/dev/null || { echo 'FAIL: go toolchain not found on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 && cp -R encoder/. "$d/" && cd "$d" || exit 1
cat > zz_evalcheck_test.go <<'EOF'
package encoder

import (
	"fmt"
	"math"
	"testing"
)

func evalBaseline(fields []Field) string {
	out := ""
	for _, f := range fields {
		out += fmt.Sprintf("%s=%d ", f.Key, f.Val)
	}
	return out
}

func TestEvalCheckEquivalent(t *testing.T) {
	big := make([]Field, 50)
	for i := range big {
		big[i] = Field{fmt.Sprintf("k%d", i), int64(i*i*7919 - 40000)}
	}
	cases := [][]Field{nil, {}, {{"", 0}}, {{"a", -1}}, {{"min", math.MinInt64}, {"max", math.MaxInt64}}, {{"ключ", 42}, {"sp ace", 7}}, big}
	for _, c := range cases {
		if got, want := Encode(c), evalBaseline(c); got != want {
			t.Errorf("Encode(%v) = %q, want %q", c, got, want)
		}
	}
}
EOF
GOTOOLCHAIN=local GOPROXY=off go test -count=1 -run '^TestEvalCheckEquivalent$' .

command -v go >/dev/null || { echo 'FAIL: go toolchain not found on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 && cp -R encoder/. "$d/" && cd "$d" || exit 1
cat > zz_evalcheck_test.go <<'EOF'
package encoder

import (
	"fmt"
	"testing"
)

func evalBaseline(fields []Field) string {
	out := ""
	for _, f := range fields {
		out += fmt.Sprintf("%s=%d ", f.Key, f.Val)
	}
	return out
}

var evalSink string

func TestEvalCheckAllocs(t *testing.T) {
	fields := make([]Field, 20)
	for i := range fields {
		fields[i] = Field{Key: "field", Val: int64(100000 + i*7919)}
	}
	base := testing.AllocsPerRun(200, func() { evalSink = evalBaseline(fields) })
	cand := testing.AllocsPerRun(200, func() { evalSink = Encode(fields) })
	t.Logf("allocs per call: baseline %.0f, candidate %.0f", base, cand)
	if cand*4 > base {
		t.Fatalf("candidate %.0f allocs per call is not under a quarter of the baseline's %.0f", cand, base)
	}
}
EOF
GOTOOLCHAIN=local GOPROXY=off go test -count=1 -v -run '^TestEvalCheckAllocs$' .

